import { defineStore } from 'pinia'

import {
  getConversationList as service_getConversationList,
  addConversation as service_addConversation,
  editConversationName as service_editConversationName,
  deleteConversation as service_deleteConversation
} from '@/services/chat'

const useChatStore = defineStore('chat', () => {
  const conversations = ref([])
  const currentConversationId = ref('')

  function getConversationList() {
    return service_getConversationList().then((res) => {
      conversations.value = res.resData || []
      return res.resData
    })
  }

  function addConversation() {
    return service_addConversation().then((res) => {
      return res.resData
    })
  }

  async function deleteConversation(id) {
    await service_deleteConversation(id)
    await getConversationList()

    // 如果删除后没有对话
    if (conversations.value.length === 0) {
      // 将示例对话插入对话表
      await addConversation()
      // 更新对话列表
      await getConversationList()
    }
    if (id === currentConversationId.value) {
      currentConversationId.value = conversations.value[0].id
    }
  }

  async function editConversationName(id, name) {
    await service_editConversationName({ id, session_name: name })
    await getConversationList()
  }

  return {
    conversations,
    currentConversationId,
    getConversationList,
    addConversation,
    editConversationName,
    deleteConversation
  }
})

export default useChatStore
