import { defineStore } from 'pinia'
import {
  createAgent as service_createAgent,
  updateAgent as service_updateAgent,
  deleteAgent as service_deleteAgent,
  getAgentList as service_getAgentList,
  getAgent as service_getAgent,
  //loadAgentInfo as service_loadAgentInfo,
  setAssistant as service_setAssistant,
  getAssistant as service_getAssistant,
  updateAssistant as service_updateAssistant,
  getAssistantList as service_getAssistantList
} from '../services/agents'
import useChatStore from '@/stores/chat'

const useAgentsStore = defineStore('agents', {
  state: () => ({
    agentList: [], // 智能体列表
    currentAgent: null, // 当前选中的智能体
    assistant: null, // 当前会话的智能体
    loading: false, // 加载状态
    error: null, // 错误信息
    assistantList: [] // 助手列表
  }),

  getters: {
    // 获取智能体列表
    getAgentList: (state) => state.agentList,
    // 获取当前智能体
    getCurrentAgent: (state) => state.currentAgent,
    // 获取会话智能体
    getAssistant: (state) => state.assistant,
    // 获取助手列表
    getAssistantList: (state) => state.assistantList
  },

  actions: {
    // 创建智能体
    async createAgent(agentData) {
      try {
        this.loading = true
        const response = await service_createAgent(agentData)
        if (response.flag === true) {
          this.agentList.push(response.resData)
          return response
        }
        // 如果flag为false，直接抛出错误对象
        throw response
      } catch (error) {
        this.error = error.errMsg || error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 更新智能体
    async updateAgent(agentId, updateData) {
      try {
        this.loading = true
        const response = await service_updateAgent({
          agent_id: agentId,
          update_val: updateData
        })
        if (response.flag === true) {
          const index = this.agentList.findIndex((agent) => agent.id === agentId)
          if (index !== -1) {
            this.agentList[index] = response.resData
          }
          if (this.currentAgent?.id === agentId) {
            this.currentAgent = response.resData
          }
          return response.resData
        }
        throw new Error(response.errMsg || '更新智能体失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 删除智能体
    async deleteAgent(agentId) {
      try {
        this.loading = true
        const response = await service_deleteAgent({ agent_id: agentId })
        if (response.flag === true) {
          this.agentList = this.agentList.filter((agent) => agent.id !== agentId)
          if (this.currentAgent?.id === agentId) {
            this.currentAgent = null
          }
          return true
        }
        throw new Error(response.errMsg || '删除智能体失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 获取智能体列表
    async fetchAgentList() {
      try {
        this.loading = true
        const response = await service_getAgentList()
        if (response && response.flag === true) {
          this.agentList = response.resData || []
        }
        return response
      } catch (error) {
        this.error = error.message || '获取智能体列表失败'
        throw error
      } finally {
        this.loading = false
      }
    },

    // 获取单个智能体
    async fetchAgent(agentId) {
      try {
        this.loading = true
        const response = await service_getAgent({ agent_id: agentId })
        if (response.flag === true) {
          this.currentAgent = response.resData
          return response.resData
        }
        throw new Error(response.errMsg || '获取智能体失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // // 加载智能体信息
    // async loadAgentInfo(sessionId) {
    //   try {
    //     this.loading = true
    //     const response = await service_loadAgentInfo({ session_id: sessionId })
    //     if (response.flag === true) {
    //       this.assistant = response.resData
    //       return response.resData
    //     }
    //     throw new Error(response.errMsg || '加载智能体信息失败')
    //   } catch (error) {
    //     this.error = error.message
    //     throw error
    //   } finally {
    //     this.loading = false
    //   }
    // },
    // 切换收藏状态
    async toggleFavorite(agentId) {
      try {
        // 找到当前智能体
        const agent = this.agentList.find((a) => a.id === agentId)
        if (!agent) {
          throw new Error(`无法找到ID为${agentId}的智能体`)
        }

        // 获取当前状态
        const currentStatus = agent ? !!agent.is_favorite : false

        // 调用API更新收藏状态
        const response = await this.updateAgent(agentId, {
          is_favorite: !currentStatus
        })

        // API调用成功后，重新获取智能体列表以确保状态同步
        if (response) {
          return true
        }

        return false
      } catch (error) {
        console.error('切换收藏状态失败:', error)
        return false
      }
    },

    // 判断智能体是否收藏（从本地状态判断）
    isAgentFavorite(agentId) {
      const agent = this.agentList.find((a) => a.id === agentId)
      return agent ? !!agent.is_favorite : false
    },

    // 获取所有收藏的智能体
    getFavoriteAgents() {
      return this.agentList.filter((agent) => agent.is_favorite)
    },
    // 设置会话助手
    async setAssistant(sessionId, agentId) {
      try {
        this.loading = true
        const response = await service_setAssistant({
          session_id: sessionId,
          agent_id: agentId
        })
        if (response.flag === true) {
          // 获取智能体信息
          const agentInfo = await service_getAgent({ agent_id: agentId })
          if (agentInfo.flag === true) {
            // 更新会话名称为智能体名称
            const chatStore = useChatStore()
            await chatStore.editConversationName(sessionId, agentInfo.resData.name)
          }
          return response.resData
        }
        throw new Error(response.errMsg || '设置会话智能体失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 获取会话助手
    async fetchAssistant(sessionId) {
      try {
        this.loading = true
        const response = await service_getAssistant({ session_id: sessionId })
        if (response.flag === true) {
          this.assistant = response.resData
          return response.resData
        }
        throw new Error(response.errMsg || '获取会话助手失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 更新会话助手
    async updateAssistant(sessionId, updateData) {
      try {
        this.loading = true
        console.log('准备发送会话助手更新请求:', { session_id: sessionId, update_val: updateData })
        const response = await service_updateAssistant({
          session_id: sessionId,
          update_val: updateData
        })
        if (response.flag === true) {
          // 更新成功后刷新助手信息
          await this.fetchAssistant(sessionId)
          return response.resData
        }
        throw new Error(response.errMsg || '更新会话助手失败')
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 获取所有助手
    async fetchAssistantList() {
      try {
        this.loading = true
        const response = await service_getAssistantList()
        if (response.flag === true) {
          this.assistantList = response.resData
        }
        return response
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    },

    // 清除状态
    clearState() {
      this.agentList = []
      this.currentAgent = null
      this.assistant = null
      this.error = null
      this.assistantList = []
    }
  }
})

export default useAgentsStore
