import request from '@/hooks/useHttp'

const baseUrl = import.meta.env.BASE_URL

// 创建智能体
export function createAgent(data) {
  return request({
    method: 'post',
    url: '/agent/create',
    data: {
      ...data,
      recommended_questions: data.recommended_questions || []
    }
  })
}

// 更新智能体
export function updateAgent(data) {
  return request({
    method: 'post',
    url: '/agent/update',
    data
  })
}

// 删除智能体
export function deleteAgent(data) {
  return request({
    method: 'post',
    url: '/agent/delete',
    data
  })
}

// 获取智能体列表
export function getAgentList() {
  return request({
    method: 'get',
    url: '/agent/getList'
  })
}

// 获取单个智能体
export function getAgent(data) {
  return request({
    method: 'post',
    url: '/agent/get',
    data
  })
}

