// 设置会话助手
export function setAssistant(data) {
  return request({
    method: 'post',
    url: '/agent/session/addAssistant',
    data
  })
}

// 获取会话助手
export function getAssistant(data) {
  return request({
    method: 'post',
    url: '/agent/session/getAssistant',
    data
  })
}
// 更新会话助手
export function updateAssistant(data) {
  console.log('原始更新助手数据:', data)
  // 确保参数格式正确
  const payload = {
    session_id: data.session_id,
    update_val: data.update_val || {}
  }
  console.log('处理后的更新助手数据:', payload)
  console.log('处理后的update_val JSON:', JSON.stringify(payload.update_val))
  return request({
    method: 'post',
    url: '/agent/session/updateAssistant',
    data: payload
  })
}

// 获取所有助手
export function getAssistantList() {
  return request({
    method: 'get',
    url: '/agent/getAssistantList'
  })
}
