import request from '@/hooks/useHttp'
import { getRandomElements } from '@/utils/util'

const baseUrl = import.meta.env.BASE_URL

export function getConversationList(params) {
  return request({
    method: 'get',
    url: '/chat/session/list',
    params
  })
}

export function addConversation(data) {
  return request({
    method: 'post',
    url: '/chat/session/create',
    data
  })
}

export async function deleteConversation(id) {
  return request({
    method: 'delete',
    url: `/chat/session/${id}`
  })
}

export function editConversationName(data) {
  return request({
    method: 'put',
    url: '/chat/session/update',
    data
  })
}

export function getMessagesByConversionId(params) {
  return request({
    method: 'get',
    url: '/chat/session/history',
    params
  })
  // return messagesDb.where('conversation_id').equals(conversation_id).toArray()
}

// 返回的推荐问题数量
const RECOMMENDS_COUNT = 3

export function getRecommendList() {
  return fetch(`${baseUrl}recommends.json`)
    .then((res) => res.json())
    .then((data) => {
      return getRandomElements(data, RECOMMENDS_COUNT)
    })
}

export function abortRequest(id) {
  return request({
    url: `/chat/infer/stop/${id}`,
    method: 'put'
  })
}

export function messageFeedback(data) {
  return request({
    method: 'put',
    url: '/chat/item/like',
    data
  })
}

export function exportChats(params) {
  return request({
    method: 'get',
    url: `/chat/session/download/${params.session_id}`,
    params,
    responseType: 'arraybuffer'
  })
}

export function deleteChatItem(params) {
  return request({
    method: 'delete',
    url: `/chat/question/${params.question_id}`,
    params
  })
}
